BEGIN;
CREATE TEMP TABLE target_ids(id int PRIMARY KEY) ON COMMIT DROP;
DO $$ BEGIN
  IF (SELECT count(*) FROM target_ids) <> 12245 THEN RAISE EXCEPTION 'loaded count is not 12245'; END IF;
  IF (SELECT count(*) FROM speech JOIN target_ids USING (id) WHERE speech.speaker IS NOT NULL) <> 12245 THEN RAISE EXCEPTION 'attributed-before count is not 12245'; END IF;
END $$;
UPDATE speech SET speaker = NULL, speaker_id = NULL FROM target_ids WHERE speech.id = target_ids.id AND speech.speaker IS NOT NULL;
DO $$ BEGIN
  IF (SELECT count(*) FROM speech JOIN target_ids USING (id) WHERE speech.speaker IS NULL AND speech.speaker_id IS NULL) <> 12245 THEN RAISE EXCEPTION 'nulled-after count is not 12245'; END IF;
END $$;
COMMIT;
